  /\ (exists tbl, bytes_at asegs mm DT4 tbl /\ Z.of_nat (length tbl) = 4096)
  /\ (exists obuf, u8arr asegs mm DST obuf /\ Z.of_nat (length obuf) = dcap)
  /\ (exists sbuf, bytes_at asegs mm SS sbuf /\ Z.of_nat (length sbuf) = n)
  /\ rw_cells asegs mm (SP + 80) [C8 (Z_to_bv 64 DT4)]
  /\ rw_cells asegs mm (SP + 136) [C8 (Z_to_bv 64 2147450880)]
  /\ unpoisoned mm DBL DBH /\ DBL <= DT4 /\ DT4 + 4096 <= DBH
  /\ unpoisoned mm DST (DST + dcap)
  /\ unpoisoned mm SBL SBH /\ SBL <= SS /\ SS + n <= SBH
  /\ rng RNG DT4 4096 /\ rng RNG DST dcap /\ rng RNG SS n /\ rng RNG SP 496 /\ rng_aimg RNG
  /\ rng RNG (shad DBL) (shlen (DBH - DBL + 7)) /\ rng RNG (shad DST) (shlen (dcap + 7))
  /\ rng RNG (shad SBL) (shlen (SBH - SBL + 7))
  /\ DBL mod 8 = 0 /\ DST mod 8 = 0 /\ SBL mod 8 = 0
  /\ 0x60d000 <= DT4 /\ DT4 + 4096 <= 2^47 /\ 0x60d000 <= DST /\ DST + dcap <= 2^47
  /\ 0x60d000 <= SS /\ SS + n <= 2^47 /\ 0x10007fff8000 <= SP /\ SP + 496 <= 2^47
  /\ 0x60d000 <= DBL /\ DBH <= 2^47 /\ 0x60d000 <= SBL /\ SBH <= 2^47
  /\ apart DST dcap 0x7fff8000 17592186044416 /\ apart DST dcap DT4 4096 /\ apart DST dcap SS n /\ apart DST dcap SP 496.

Ltac w4kx_intro C :=
  let MI := fresh "MI" in let tbl := fresh "tbl" in let TB := fresh "TB" in let TL := fresh "TL" in
  let obuf := fresh "obuf" in let OB := fresh "OB" in let OL := fresh "OL" in
  let sbuf := fresh "sbuf" in let SB := fresh "SB" in let SL := fresh "SL" in
  destruct C as (MI & (tbl & TB & TL) & (obuf & OB & OL) & (sbuf & SB & SL) & ?FR1 & ?FR2 & ?UT & ?UT1 & ?UT2 & ?UD
                 & ?US & ?US1 & ?US2 & ?WT & ?WD & ?WS & ?WF & ?WI & ?WTS & ?WDS & ?WSS & ?A8a & ?A8b & ?A8c
                 & ?R1 & ?R2 & ?R3 & ?R4 & ?R5 & ?R6 & ?R7 & ?R8 & ?R9 & ?R10 & ?R11 & ?R12 & ?AB & ?AT & ?AS & ?AF).

(* [comment removed for export] *)
Ltac w4_rng :=
  lazymatch goal with
  | |- ?lo <= bv_unsigned (ev ?E ?j) <= ?hi => let H := fresh "H" in kx_range (EVar j) H; exact H
  end.

