Definition w4_S_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (gp tp x1 x5 x6 x7 x8 x9 x12 x14 x15 x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 x29 x31 : word)
         (SP DT4 DBL DBH DST dcap SS n SBL SBH IP K8 SE OP : Z) (wsb : list byte),
    w4kx_ctx RNG mm SP DT4 DBL DBH DST dcap SS n SBL SBH ->
    SS <= IP -> IP + 8 <= SS + n -> K8 = 0 \/ K8 = 8 \/ K8 = 16 \/ K8 = 24 ->
    bytes_at asegs mm (SP + 240) wsb -> Z.of_nat (length wsb) = 152 ->
    rw_cells asegs mm (SP + 344) [C8 (Z_to_bv 64 SS)] ->
    0 <= SE < 2^64 -> 0 <= OP <= SE ->
    ( forall (y7 y11 y12 y31 c bc : word), 0 <= bv_unsigned bc <= 63 ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 SP) gp tp x5 x6 y7 x8 (Z_to_bv 64 (SE - OP)) (Z_to_bv 64 IP) y11 y12 (Z_to_bv 64 OP) x14 x15 (Z_to_bv 64 151050438420815295) x17 bc (Z_to_bv 64 SS) (Z_to_bv 64 (SS + 8)) x21 x22 x23 x24 x25 x26 x27 (Z_to_bv 64 0x20dc4) c (Z_to_bv 64 SE) y31)
                            F (Z_to_bv 64 0x8fba4) fc None mm (seg_rom asegs))) ->
    evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 SP) gp tp x5 x6 x7 x8 x9 (Z_to_bv 64 IP) (Z_to_bv 64 K8) x12 (Z_to_bv 64 OP) x14 x15 (Z_to_bv 64 151050438420815295) x17 x18 x19 x20 x21 x22 x23 x24 x25 x26 x27 (Z_to_bv 64 0x20dc4) x29 (Z_to_bv 64 SE) x31)
                        F (Z_to_bv 64 0x8faf4) fc None mm (seg_rom asegs)).

